BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"g":1,"sem":1,"n":1,"title":"الاستماع والتحدث — الفصل الأول","activity3":"listening","skill":"الاستماع لتسلسل قصة قصيرة","passage":"يقرأ المعلم بصوت واضح: «دخلت سلمى الصف، ووضعت حقيبتها، ثم حيّت زميلاتها». نلاحظ ترتيب الأفعال ونجيب عن السؤال بما ورد لا بما نتخيله. هذا نص تدريبي أصلي؛ يحتاج نشاط الاستماع الفعلي إلى قراءة صوتية من المعلم ولا يحتوي على تسجيل صوتي جاهز.","q1":"ماذا وضعت سلمى في الصف؟","a1":"حقيبتها","w1":["كتاب المكتبة","طعامها","زهرة"],"q2":"ماذا فعلت بعد وضع الحقيبة؟","a2":"حيّت زميلاتها","w2":["عادت إلى البيت","لعبت كرة","رسمت لوحة"],"practice":"اسمع القصة حين يقرأها المعلم، ثم أعد سرد أحداثها الثلاثة بترتيبها. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":1,"sem":1,"n":2,"title":"القراءة والفهم — الفصل الأول","activity3":"reading","skill":"القراءة والفهم من جمل مترابطة","passage":"«زرعَ سامي بذرةً في كوبٍ، وسقاها كل يوم. بعد أيام ظهرت نبتة صغيرة». يقرأ الطالب الكلمات بهدوء ويبحث عن المكان والعمل والنتيجة. نميز ما ورد في النص عن معلومة نتخيلها؛ لم تذكر القصة لون النبتة.","q1":"أين زرع سامي البذرة؟","a1":"في كوب","w1":["في البحر","على سطح سيارة","في صندوق كتب"],"q2":"ماذا ظهر بعد أيام؟","a2":"نبتة صغيرة","w2":["طائر","مفتاح","كرسي"],"practice":"اقرأ القصة مع المعلم وحدد المكان والفعل والنتيجة في جمل بسيطة. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":1,"sem":1,"n":3,"title":"الصنف اللغوي — الفصل الأول","activity3":"writing","skill":"الصنف اللغوي: الاسم والفعل","passage":"«كتاب» اسم يدل على شيء، و«يلعب» فعل يدل على حدث، و«في» حرف جر. نقرأ الكلمات في جمل مثل «الطفل يلعب في الحديقة» ونرى أن لكل كلمة عملًا. لا نتسرع في تصنيف الكلمة من طولها أو شكل حروفها.","q1":"أي كلمة من الكلمات الآتية اسم؟","a1":"كتاب","w1":["يلعب","في","لن"],"q2":"أي كلمة تدل على فعل؟","a2":"يلعب","w2":["كرسي","مدرسة","هذا"],"practice":"كوّن ثلاث جمل قصيرة، واستخرج اسمًا وفعلًا وحرفًا من كل جملة بمساعدة المعلم. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":1,"sem":1,"n":4,"title":"الوظيفة النحوية — الفصل الأول","activity3":"writing","skill":"الوظيفة النحوية في الجملة البسيطة","passage":"«الحديقةُ جميلةٌ» جملة تخبرنا عن الحديقة بصفة جميلة؛ و«الطالبُ نشيطٌ» تخبرنا عن الطالب بالنشاط. نتعلم أن الجملة المفيدة تقول شيئًا واضحًا عن موضوعها، ويبدأ المتعلم بتمييز عمّا نتحدث وما نقوله عنه دون تعقيد.","q1":"عم نتحدث في «الحديقة جميلة»؟","a1":"الحديقة","w1":["الطالب","الكرسي","المفتاح"],"q2":"ماذا نقول عن الطالب في «الطالب نشيط»؟","a2":"إنه نشيط","w2":["إنه نائم","إنه مسافر","إنه طويل حتمًا"],"practice":"اكتب جملتين: واحدة عن المدرسة وأخرى عن صديق، وحدد الموضوع وما تخبر به عنه. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":1,"sem":1,"n":5,"title":"الأسلوب اللغوي — الفصل الأول","activity3":"reading","skill":"الأسلوب اللغوي: السؤال بأين ومتى","passage":"نستخدم «أين» للسؤال عن المكان مثل «أين الكتاب؟»، ونستخدم «متى» للسؤال عن الوقت مثل «متى تبدأ الحصة؟». تساعد أداة السؤال على معرفة نوع الجواب المطلوب. نقرأ جملة السؤال بنبرة مناسبة ونضع علامة الاستفهام في آخرها.","q1":"أي أداة نسأل بها عن المكان؟","a1":"أين","w1":["متى","لماذا","كيف"],"q2":"أي أداة نسأل بها عن الوقت؟","a2":"متى","w2":["أين","من","ماذا"],"practice":"اكتب سؤالًا عن مكان الحقيبة وسؤالًا عن وقت بدء اللعب، ثم اسأل زميلك. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":1,"sem":1,"n":6,"title":"الظاهرة الإملائية — الفصل الأول","activity3":"writing","skill":"الظاهرة الإملائية: التاء في آخر الكلمة","passage":"تنتهي «شجرة» بتاء مربوطة «ة»، وتنتهي «بيت» بتاء مفتوحة «ت»، وتنتهي «وجه» بهاء «ه». نتأمل صورة آخر حرف وننطق الكلمة مع المعلم، ولا نستبدل الحروف عشوائيًا. يساعد جمع بعض الكلمات على تمييز التاء.","q1":"بأي حرف تنتهي «شجرة»؟","a1":"تاء مربوطة","w1":["تاء مفتوحة","هاء أصلية","واو"],"q2":"بأي حرف تنتهي «بيت»؟","a2":"تاء مفتوحة","w2":["تاء مربوطة","هاء","ألف"],"practice":"اكتب ست كلمات فيها تاء مربوطة ومفتوحة، ولوّن الحرف الأخير بلون مختلف. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":1,"sem":1,"n":7,"title":"الرسم الكتابي — الفصل الأول","activity3":"writing","skill":"الرسم الكتابي: حروف واضحة ومسافات","passage":"نكتب الكلمات من اليمين إلى اليسار، ونترك مسافة صغيرة واضحة بين كل كلمتين، مع المحافظة على مواضع النقاط. في «ذهبَ عليٌّ إلى البيت» نلاحظ أن الكلمات ثلاث وحدات متباعدة، وأن للحروف نقاطًا لا يجوز نسيانها.","q1":"ما الذي نفصل به بين كلمتين؟","a1":"مسافة مناسبة","w1":["نقطة فوق كل حرف","شرطة بين كل حرف","حذف آخر الحرف"],"q2":"ما الذي يجب المحافظة عليه عند كتابة «بيت»؟","a2":"شكل الحروف ونقاطها","w2":["إزالة النقاط","جمع الكلمات","قلب الاتجاه"],"practice":"انسخ ثلاث جمل قصيرة بخط واضح مع مسافات متساوية، ثم راجع النقاط. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":1,"sem":1,"n":8,"title":"التواصل الكتابي — الفصل الأول","activity3":"writing","skill":"التواصل الكتابي: بداية ووسط ونهاية","passage":"يمكن كتابة قصة صغيرة من ثلاث جمل: «أحضرَ فهدٌ ورقة. رسم شجرة جميلة. علّق الرسم في الفصل». تبدأ القصة بفكرة ثم حدث ثم نتيجة. يكتب الطالب جملة مفيدة بكل سطر ويختار كلمة مناسبة للتسلسل.","q1":"ماذا فعل فهد في الجملة الثانية؟","a1":"رسم شجرة","w1":["ذهب إلى البحر","أكل تفاحة","قرأ قصة"],"q2":"ما آخر حدث في القصة؟","a2":"علّق الرسم","w2":["أحضر الورقة","فتح الباب","زرع بذرة"],"practice":"اكتب ثلاث جمل عن عمل قمت به: البداية، ثم ما فعلته، ثم النتيجة. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":1,"sem":2,"n":1,"title":"الاستماع والتحدث — الفصل الثاني","activity3":"listening","skill":"الاستماع لفكرة النص والسبب","passage":"يقرأ المعلم: «استعار ناصر قصةً من مكتبة المدرسة. أعادها يوم الخميس؛ لأنه وعد أمين المكتبة بالحفاظ على الموعد». نص تدريبي أصلي يحتاج قراءة صوتية فعلية ولا يتضمن ملفًا صوتيًا مولدًا. يستمع الطالب بحثًا عن الفعل والسبب.","q1":"لماذا أعاد ناصر القصة يوم الخميس؟","a1":"لأنه وعد بالمحافظة على الموعد","w1":["لأن الحديقة أغلقت","لأنه نسي عنوانها","لأنه أراد إخفاءها"],"q2":"من أين استعار ناصر القصة؟","a2":"من مكتبة المدرسة","w2":["من متجر الألعاب","من محطة القطار","من الملعب"],"practice":"استمع للقصة واذكر سبب إعادة الكتاب ثم أعدها بجملة من إنشائك. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":1,"sem":2,"n":2,"title":"القراءة والفهم — الفصل الثاني","activity3":"reading","skill":"القراءة: ترتيب الأحداث والنتيجة","passage":"«وصلَ كريم إلى البستان. رأى الورود عطشى، فسقاها بالماء. في المساء بدت الأوراق نضرة». نقرأ النص ونحدد البداية والفعل الذي أدى إلى النتيجة. لا يصح أن ندّعي أن القصة تحدثت عن المطر؛ لم تذكره.","q1":"ماذا فعل كريم للورود؟","a1":"سقاها بالماء","w1":["قطفها كلها","نقلها إلى الصف","باعها"],"q2":"كيف بدت الأوراق في المساء؟","a2":"نضرة","w2":["ممزقة","مفقودة","ملونة بالأحمر حتمًا"],"practice":"رتب أحداث القصة باستخدام «أولًا، ثم، أخيرًا» واكتب جملة عن النتيجة. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":1,"sem":2,"n":3,"title":"الصنف اللغوي — الفصل الثاني","activity3":"writing","skill":"الصنف اللغوي: الجمع والمفرد","passage":"كلمة «قلم» مفرد، و«أقلام» جمع تكسير، و«طالبة» مفرد و«طالبات» جمع مؤنث سالم. يتغير شكل بعض الكلمات عند جمعها ولا يلزم أن يضاف حرف واحد في جميع الجموع. يراجع المتعلم المعنى وعدد الأشياء.","q1":"أي كلمة جمع لكلمة «قلم»؟","a1":"أقلام","w1":["قلمة","قلمان فقط","كتب"],"q2":"ما جمع «طالبة»؟","a2":"طالبات","w2":["طلابان","طالبي","قلمين"],"practice":"كوّن قائمة بخمسة أسماء مفردة وجموعها واستخدم كل جمع في جملة. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":1,"sem":2,"n":4,"title":"الوظيفة النحوية — الفصل الثاني","activity3":"writing","skill":"الوظيفة النحوية: فعل ومن قام به","passage":"في «فتحَ أحمدُ البابَ» يدل «فتحَ» على فعل، و«أحمدُ» من قام به، و«البابَ» الشيء الذي وقع عليه الفتح. يكفي للمتعلم في البداية فهم العلاقات داخل الجملة، ثم يتعرف بالتدريج إلى تسمية الفاعل والمفعول.","q1":"من قام بالفتح؟","a1":"أحمد","w1":["الباب","النافذة","القلم"],"q2":"ماذا فتح أحمد؟","a2":"الباب","w2":["الكتاب","الحقيبة","السيارة"],"practice":"اكتب ثلاث جمل عن أعمال منزلية آمنة ثم حدد من فعل العمل وما وقع عليه. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":1,"sem":2,"n":5,"title":"الأسلوب اللغوي — الفصل الثاني","activity3":"reading","skill":"الأسلوب اللغوي: النفي والطلب المهذب","passage":"«لا أعبثُ بالكتب» تعبير عن نفي فعل المتكلم في هذا السياق، و«من فضلك رتّب الكتب» طلب مهذب. تختلف صياغة الكلام بحسب المتحدث والمخاطب؛ نختار التعبير الواضح ولا نستعمل السخرية أو التجريح.","q1":"أي عبارة طلب مهذب؟","a1":"من فضلك رتّب الكتب","w1":["أنت لا تفهم","لا أريد الاستماع","كل كلامك خاطئ"],"q2":"ما الذي يفيده قول «لا أعبث بالكتب»؟","a2":"نفي العبث بالكتب","w2":["إثبات العبث","سؤال عن المكان","تعجب من الطقس"],"practice":"حوّل أمرين مباشرين إلى طلبين مهذبين، واكتب جملة نفي من إنشائك. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":1,"sem":2,"n":6,"title":"الظاهرة الإملائية — الفصل الثاني","activity3":"writing","skill":"الظاهرة الإملائية: حروف المد","passage":"في «قال» ألف مد بعد فتحة، وفي «يقول» واو مد بعد ضمة، وفي «قيل» ياء مد بعد كسرة. ننطق المقاطع بتمهل لنربط الصوت الطويل بحرفه، ولا نضيف حرف مد حيث لا يسمع الصوت الطويل في المثال.","q1":"ما حرف المد في «قال»؟","a1":"الألف","w1":["الواو","الياء","الهمزة"],"q2":"ما حرف المد في «قيل»؟","a2":"الياء","w2":["الألف","الواو","التاء"],"practice":"اكتب ثلاثة أمثلة لكل مد بالألف والواو والياء ثم اقرأها بصوت واضح. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":1,"sem":2,"n":7,"title":"الرسم الكتابي — الفصل الثاني","activity3":"writing","skill":"الرسم الكتابي: اتصال الحروف","passage":"في الكتابة العربية تتصل حروف كثيرة بما بعدها مثل الباء والسين في مواضعها، وهناك حروف لا تتصل بما بعدها مثل الألف والدال والراء. يساعد نسخ «باب» و«مدرسة» على ملاحظة بداية الكلمة ووسطها ونهايتها، ولا يتغير ترتيب الحروف.","q1":"أي حرف لا يتصل بما بعده عادة؟","a1":"الدال","w1":["الباء","السين","الميم"],"q2":"ما العنصر الذي نراجعه عند نسخ كلمة؟","a2":"اتصال الحروف ونقاطها وترتيبها","w2":["لون الورقة وحده","طول السطر فقط","الزينة حول الكلمة"],"practice":"انسخ كلمتين بحروف متصلة وأخريين تضمان حرفًا لا يتصل بما بعده، ووضّح مواضع الوصل. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":1,"sem":2,"n":8,"title":"التواصل الكتابي — الفصل الثاني","activity3":"writing","skill":"التواصل الكتابي: رسالة قصيرة","passage":"تتضمن الرسالة الودية تحية وسبب الكتابة وخاتمة لطيفة. مثال أصلي: «إلى صديقي سامي، أحب أن أخبرك أنني قرأت قصة ممتعة. هل ترغب في استعارتها؟ تحياتي، خالد». يحافظ الكاتب على وضوح المقصود واحترام المخاطب.","q1":"لمن وجّه خالد رسالته؟","a1":"إلى سامي","w1":["إلى المعلم فقط","إلى المدير","إلى أبيه"],"q2":"ماذا عرض خالد في الرسالة؟","a2":"إعارة قصة","w2":["شراء سيارة","إلغاء الرحلة","بيع مكتبة"],"practice":"اكتب رسالة من أربع جمل لصديق تشكره أو تدعوه لنشاط مناسب. مستوى الصف 1: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 1 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":2,"sem":1,"n":1,"title":"الاستماع والتحدث — الفصل الأول","activity3":"listening","skill":"الاستماع لتسلسل قصة قصيرة","passage":"يقرأ المعلم بصوت واضح: «دخلت سلمى الصف، ووضعت حقيبتها، ثم حيّت زميلاتها». نلاحظ ترتيب الأفعال ونجيب عن السؤال بما ورد لا بما نتخيله. هذا نص تدريبي أصلي؛ يحتاج نشاط الاستماع الفعلي إلى قراءة صوتية من المعلم ولا يحتوي على تسجيل صوتي جاهز.","q1":"ماذا وضعت سلمى في الصف؟","a1":"حقيبتها","w1":["كتاب المكتبة","طعامها","زهرة"],"q2":"ماذا فعلت بعد وضع الحقيبة؟","a2":"حيّت زميلاتها","w2":["عادت إلى البيت","لعبت كرة","رسمت لوحة"],"practice":"اسمع القصة حين يقرأها المعلم، ثم أعد سرد أحداثها الثلاثة بترتيبها. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":2,"sem":1,"n":2,"title":"القراءة والفهم — الفصل الأول","activity3":"reading","skill":"القراءة والفهم من جمل مترابطة","passage":"«زرعَ سامي بذرةً في كوبٍ، وسقاها كل يوم. بعد أيام ظهرت نبتة صغيرة». يقرأ الطالب الكلمات بهدوء ويبحث عن المكان والعمل والنتيجة. نميز ما ورد في النص عن معلومة نتخيلها؛ لم تذكر القصة لون النبتة.","q1":"أين زرع سامي البذرة؟","a1":"في كوب","w1":["في البحر","على سطح سيارة","في صندوق كتب"],"q2":"ماذا ظهر بعد أيام؟","a2":"نبتة صغيرة","w2":["طائر","مفتاح","كرسي"],"practice":"اقرأ القصة مع المعلم وحدد المكان والفعل والنتيجة في جمل بسيطة. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":2,"sem":1,"n":3,"title":"الصنف اللغوي — الفصل الأول","activity3":"writing","skill":"الصنف اللغوي: الاسم والفعل","passage":"«كتاب» اسم يدل على شيء، و«يلعب» فعل يدل على حدث، و«في» حرف جر. نقرأ الكلمات في جمل مثل «الطفل يلعب في الحديقة» ونرى أن لكل كلمة عملًا. لا نتسرع في تصنيف الكلمة من طولها أو شكل حروفها.","q1":"أي كلمة من الكلمات الآتية اسم؟","a1":"كتاب","w1":["يلعب","في","لن"],"q2":"أي كلمة تدل على فعل؟","a2":"يلعب","w2":["كرسي","مدرسة","هذا"],"practice":"كوّن ثلاث جمل قصيرة، واستخرج اسمًا وفعلًا وحرفًا من كل جملة بمساعدة المعلم. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":2,"sem":1,"n":4,"title":"الوظيفة النحوية — الفصل الأول","activity3":"writing","skill":"الوظيفة النحوية في الجملة البسيطة","passage":"«الحديقةُ جميلةٌ» جملة تخبرنا عن الحديقة بصفة جميلة؛ و«الطالبُ نشيطٌ» تخبرنا عن الطالب بالنشاط. نتعلم أن الجملة المفيدة تقول شيئًا واضحًا عن موضوعها، ويبدأ المتعلم بتمييز عمّا نتحدث وما نقوله عنه دون تعقيد.","q1":"عم نتحدث في «الحديقة جميلة»؟","a1":"الحديقة","w1":["الطالب","الكرسي","المفتاح"],"q2":"ماذا نقول عن الطالب في «الطالب نشيط»؟","a2":"إنه نشيط","w2":["إنه نائم","إنه مسافر","إنه طويل حتمًا"],"practice":"اكتب جملتين: واحدة عن المدرسة وأخرى عن صديق، وحدد الموضوع وما تخبر به عنه. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":2,"sem":1,"n":5,"title":"الأسلوب اللغوي — الفصل الأول","activity3":"reading","skill":"الأسلوب اللغوي: السؤال بأين ومتى","passage":"نستخدم «أين» للسؤال عن المكان مثل «أين الكتاب؟»، ونستخدم «متى» للسؤال عن الوقت مثل «متى تبدأ الحصة؟». تساعد أداة السؤال على معرفة نوع الجواب المطلوب. نقرأ جملة السؤال بنبرة مناسبة ونضع علامة الاستفهام في آخرها.","q1":"أي أداة نسأل بها عن المكان؟","a1":"أين","w1":["متى","لماذا","كيف"],"q2":"أي أداة نسأل بها عن الوقت؟","a2":"متى","w2":["أين","من","ماذا"],"practice":"اكتب سؤالًا عن مكان الحقيبة وسؤالًا عن وقت بدء اللعب، ثم اسأل زميلك. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":2,"sem":1,"n":6,"title":"الظاهرة الإملائية — الفصل الأول","activity3":"writing","skill":"الظاهرة الإملائية: التاء في آخر الكلمة","passage":"تنتهي «شجرة» بتاء مربوطة «ة»، وتنتهي «بيت» بتاء مفتوحة «ت»، وتنتهي «وجه» بهاء «ه». نتأمل صورة آخر حرف وننطق الكلمة مع المعلم، ولا نستبدل الحروف عشوائيًا. يساعد جمع بعض الكلمات على تمييز التاء.","q1":"بأي حرف تنتهي «شجرة»؟","a1":"تاء مربوطة","w1":["تاء مفتوحة","هاء أصلية","واو"],"q2":"بأي حرف تنتهي «بيت»؟","a2":"تاء مفتوحة","w2":["تاء مربوطة","هاء","ألف"],"practice":"اكتب ست كلمات فيها تاء مربوطة ومفتوحة، ولوّن الحرف الأخير بلون مختلف. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":2,"sem":1,"n":7,"title":"الرسم الكتابي — الفصل الأول","activity3":"writing","skill":"الرسم الكتابي: حروف واضحة ومسافات","passage":"نكتب الكلمات من اليمين إلى اليسار، ونترك مسافة صغيرة واضحة بين كل كلمتين، مع المحافظة على مواضع النقاط. في «ذهبَ عليٌّ إلى البيت» نلاحظ أن الكلمات ثلاث وحدات متباعدة، وأن للحروف نقاطًا لا يجوز نسيانها.","q1":"ما الذي نفصل به بين كلمتين؟","a1":"مسافة مناسبة","w1":["نقطة فوق كل حرف","شرطة بين كل حرف","حذف آخر الحرف"],"q2":"ما الذي يجب المحافظة عليه عند كتابة «بيت»؟","a2":"شكل الحروف ونقاطها","w2":["إزالة النقاط","جمع الكلمات","قلب الاتجاه"],"practice":"انسخ ثلاث جمل قصيرة بخط واضح مع مسافات متساوية، ثم راجع النقاط. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":2,"sem":1,"n":8,"title":"التواصل الكتابي — الفصل الأول","activity3":"writing","skill":"التواصل الكتابي: بداية ووسط ونهاية","passage":"يمكن كتابة قصة صغيرة من ثلاث جمل: «أحضرَ فهدٌ ورقة. رسم شجرة جميلة. علّق الرسم في الفصل». تبدأ القصة بفكرة ثم حدث ثم نتيجة. يكتب الطالب جملة مفيدة بكل سطر ويختار كلمة مناسبة للتسلسل.","q1":"ماذا فعل فهد في الجملة الثانية؟","a1":"رسم شجرة","w1":["ذهب إلى البحر","أكل تفاحة","قرأ قصة"],"q2":"ما آخر حدث في القصة؟","a2":"علّق الرسم","w2":["أحضر الورقة","فتح الباب","زرع بذرة"],"practice":"اكتب ثلاث جمل عن عمل قمت به: البداية، ثم ما فعلته، ثم النتيجة. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":2,"sem":2,"n":1,"title":"الاستماع والتحدث — الفصل الثاني","activity3":"listening","skill":"الاستماع لفكرة النص والسبب","passage":"يقرأ المعلم: «استعار ناصر قصةً من مكتبة المدرسة. أعادها يوم الخميس؛ لأنه وعد أمين المكتبة بالحفاظ على الموعد». نص تدريبي أصلي يحتاج قراءة صوتية فعلية ولا يتضمن ملفًا صوتيًا مولدًا. يستمع الطالب بحثًا عن الفعل والسبب.","q1":"لماذا أعاد ناصر القصة يوم الخميس؟","a1":"لأنه وعد بالمحافظة على الموعد","w1":["لأن الحديقة أغلقت","لأنه نسي عنوانها","لأنه أراد إخفاءها"],"q2":"من أين استعار ناصر القصة؟","a2":"من مكتبة المدرسة","w2":["من متجر الألعاب","من محطة القطار","من الملعب"],"practice":"استمع للقصة واذكر سبب إعادة الكتاب ثم أعدها بجملة من إنشائك. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":2,"sem":2,"n":2,"title":"القراءة والفهم — الفصل الثاني","activity3":"reading","skill":"القراءة: ترتيب الأحداث والنتيجة","passage":"«وصلَ كريم إلى البستان. رأى الورود عطشى، فسقاها بالماء. في المساء بدت الأوراق نضرة». نقرأ النص ونحدد البداية والفعل الذي أدى إلى النتيجة. لا يصح أن ندّعي أن القصة تحدثت عن المطر؛ لم تذكره.","q1":"ماذا فعل كريم للورود؟","a1":"سقاها بالماء","w1":["قطفها كلها","نقلها إلى الصف","باعها"],"q2":"كيف بدت الأوراق في المساء؟","a2":"نضرة","w2":["ممزقة","مفقودة","ملونة بالأحمر حتمًا"],"practice":"رتب أحداث القصة باستخدام «أولًا، ثم، أخيرًا» واكتب جملة عن النتيجة. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":2,"sem":2,"n":3,"title":"الصنف اللغوي — الفصل الثاني","activity3":"writing","skill":"الصنف اللغوي: الجمع والمفرد","passage":"كلمة «قلم» مفرد، و«أقلام» جمع تكسير، و«طالبة» مفرد و«طالبات» جمع مؤنث سالم. يتغير شكل بعض الكلمات عند جمعها ولا يلزم أن يضاف حرف واحد في جميع الجموع. يراجع المتعلم المعنى وعدد الأشياء.","q1":"أي كلمة جمع لكلمة «قلم»؟","a1":"أقلام","w1":["قلمة","قلمان فقط","كتب"],"q2":"ما جمع «طالبة»؟","a2":"طالبات","w2":["طلابان","طالبي","قلمين"],"practice":"كوّن قائمة بخمسة أسماء مفردة وجموعها واستخدم كل جمع في جملة. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":2,"sem":2,"n":4,"title":"الوظيفة النحوية — الفصل الثاني","activity3":"writing","skill":"الوظيفة النحوية: فعل ومن قام به","passage":"في «فتحَ أحمدُ البابَ» يدل «فتحَ» على فعل، و«أحمدُ» من قام به، و«البابَ» الشيء الذي وقع عليه الفتح. يكفي للمتعلم في البداية فهم العلاقات داخل الجملة، ثم يتعرف بالتدريج إلى تسمية الفاعل والمفعول.","q1":"من قام بالفتح؟","a1":"أحمد","w1":["الباب","النافذة","القلم"],"q2":"ماذا فتح أحمد؟","a2":"الباب","w2":["الكتاب","الحقيبة","السيارة"],"practice":"اكتب ثلاث جمل عن أعمال منزلية آمنة ثم حدد من فعل العمل وما وقع عليه. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":2,"sem":2,"n":5,"title":"الأسلوب اللغوي — الفصل الثاني","activity3":"reading","skill":"الأسلوب اللغوي: النفي والطلب المهذب","passage":"«لا أعبثُ بالكتب» تعبير عن نفي فعل المتكلم في هذا السياق، و«من فضلك رتّب الكتب» طلب مهذب. تختلف صياغة الكلام بحسب المتحدث والمخاطب؛ نختار التعبير الواضح ولا نستعمل السخرية أو التجريح.","q1":"أي عبارة طلب مهذب؟","a1":"من فضلك رتّب الكتب","w1":["أنت لا تفهم","لا أريد الاستماع","كل كلامك خاطئ"],"q2":"ما الذي يفيده قول «لا أعبث بالكتب»؟","a2":"نفي العبث بالكتب","w2":["إثبات العبث","سؤال عن المكان","تعجب من الطقس"],"practice":"حوّل أمرين مباشرين إلى طلبين مهذبين، واكتب جملة نفي من إنشائك. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":2,"sem":2,"n":6,"title":"الظاهرة الإملائية — الفصل الثاني","activity3":"writing","skill":"الظاهرة الإملائية: حروف المد","passage":"في «قال» ألف مد بعد فتحة، وفي «يقول» واو مد بعد ضمة، وفي «قيل» ياء مد بعد كسرة. ننطق المقاطع بتمهل لنربط الصوت الطويل بحرفه، ولا نضيف حرف مد حيث لا يسمع الصوت الطويل في المثال.","q1":"ما حرف المد في «قال»؟","a1":"الألف","w1":["الواو","الياء","الهمزة"],"q2":"ما حرف المد في «قيل»؟","a2":"الياء","w2":["الألف","الواو","التاء"],"practice":"اكتب ثلاثة أمثلة لكل مد بالألف والواو والياء ثم اقرأها بصوت واضح. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":2,"sem":2,"n":7,"title":"الرسم الكتابي — الفصل الثاني","activity3":"writing","skill":"الرسم الكتابي: اتصال الحروف","passage":"في الكتابة العربية تتصل حروف كثيرة بما بعدها مثل الباء والسين في مواضعها، وهناك حروف لا تتصل بما بعدها مثل الألف والدال والراء. يساعد نسخ «باب» و«مدرسة» على ملاحظة بداية الكلمة ووسطها ونهايتها، ولا يتغير ترتيب الحروف.","q1":"أي حرف لا يتصل بما بعده عادة؟","a1":"الدال","w1":["الباء","السين","الميم"],"q2":"ما العنصر الذي نراجعه عند نسخ كلمة؟","a2":"اتصال الحروف ونقاطها وترتيبها","w2":["لون الورقة وحده","طول السطر فقط","الزينة حول الكلمة"],"practice":"انسخ كلمتين بحروف متصلة وأخريين تضمان حرفًا لا يتصل بما بعده، ووضّح مواضع الوصل. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":2,"sem":2,"n":8,"title":"التواصل الكتابي — الفصل الثاني","activity3":"writing","skill":"التواصل الكتابي: رسالة قصيرة","passage":"تتضمن الرسالة الودية تحية وسبب الكتابة وخاتمة لطيفة. مثال أصلي: «إلى صديقي سامي، أحب أن أخبرك أنني قرأت قصة ممتعة. هل ترغب في استعارتها؟ تحياتي، خالد». يحافظ الكاتب على وضوح المقصود واحترام المخاطب.","q1":"لمن وجّه خالد رسالته؟","a1":"إلى سامي","w1":["إلى المعلم فقط","إلى المدير","إلى أبيه"],"q2":"ماذا عرض خالد في الرسالة؟","a2":"إعارة قصة","w2":["شراء سيارة","إلغاء الرحلة","بيع مكتبة"],"practice":"اكتب رسالة من أربع جمل لصديق تشكره أو تدعوه لنشاط مناسب. مستوى الصف 2: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 2 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":3,"sem":1,"n":1,"title":"الاستماع والتحدث — الفصل الأول","activity3":"listening","skill":"الاستماع لتسلسل قصة قصيرة","passage":"يقرأ المعلم بصوت واضح: «دخلت سلمى الصف، ووضعت حقيبتها، ثم حيّت زميلاتها». نلاحظ ترتيب الأفعال ونجيب عن السؤال بما ورد لا بما نتخيله. هذا نص تدريبي أصلي؛ يحتاج نشاط الاستماع الفعلي إلى قراءة صوتية من المعلم ولا يحتوي على تسجيل صوتي جاهز.","q1":"ماذا وضعت سلمى في الصف؟","a1":"حقيبتها","w1":["كتاب المكتبة","طعامها","زهرة"],"q2":"ماذا فعلت بعد وضع الحقيبة؟","a2":"حيّت زميلاتها","w2":["عادت إلى البيت","لعبت كرة","رسمت لوحة"],"practice":"اسمع القصة حين يقرأها المعلم، ثم أعد سرد أحداثها الثلاثة بترتيبها. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":3,"sem":1,"n":2,"title":"القراءة والفهم — الفصل الأول","activity3":"reading","skill":"القراءة والفهم من جمل مترابطة","passage":"«زرعَ سامي بذرةً في كوبٍ، وسقاها كل يوم. بعد أيام ظهرت نبتة صغيرة». يقرأ الطالب الكلمات بهدوء ويبحث عن المكان والعمل والنتيجة. نميز ما ورد في النص عن معلومة نتخيلها؛ لم تذكر القصة لون النبتة.","q1":"أين زرع سامي البذرة؟","a1":"في كوب","w1":["في البحر","على سطح سيارة","في صندوق كتب"],"q2":"ماذا ظهر بعد أيام؟","a2":"نبتة صغيرة","w2":["طائر","مفتاح","كرسي"],"practice":"اقرأ القصة مع المعلم وحدد المكان والفعل والنتيجة في جمل بسيطة. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":3,"sem":1,"n":3,"title":"الصنف اللغوي — الفصل الأول","activity3":"writing","skill":"الصنف اللغوي: الاسم والفعل","passage":"«كتاب» اسم يدل على شيء، و«يلعب» فعل يدل على حدث، و«في» حرف جر. نقرأ الكلمات في جمل مثل «الطفل يلعب في الحديقة» ونرى أن لكل كلمة عملًا. لا نتسرع في تصنيف الكلمة من طولها أو شكل حروفها.","q1":"أي كلمة من الكلمات الآتية اسم؟","a1":"كتاب","w1":["يلعب","في","لن"],"q2":"أي كلمة تدل على فعل؟","a2":"يلعب","w2":["كرسي","مدرسة","هذا"],"practice":"كوّن ثلاث جمل قصيرة، واستخرج اسمًا وفعلًا وحرفًا من كل جملة بمساعدة المعلم. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":3,"sem":1,"n":4,"title":"الوظيفة النحوية — الفصل الأول","activity3":"writing","skill":"الوظيفة النحوية في الجملة البسيطة","passage":"«الحديقةُ جميلةٌ» جملة تخبرنا عن الحديقة بصفة جميلة؛ و«الطالبُ نشيطٌ» تخبرنا عن الطالب بالنشاط. نتعلم أن الجملة المفيدة تقول شيئًا واضحًا عن موضوعها، ويبدأ المتعلم بتمييز عمّا نتحدث وما نقوله عنه دون تعقيد.","q1":"عم نتحدث في «الحديقة جميلة»؟","a1":"الحديقة","w1":["الطالب","الكرسي","المفتاح"],"q2":"ماذا نقول عن الطالب في «الطالب نشيط»؟","a2":"إنه نشيط","w2":["إنه نائم","إنه مسافر","إنه طويل حتمًا"],"practice":"اكتب جملتين: واحدة عن المدرسة وأخرى عن صديق، وحدد الموضوع وما تخبر به عنه. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":3,"sem":1,"n":5,"title":"الأسلوب اللغوي — الفصل الأول","activity3":"reading","skill":"الأسلوب اللغوي: السؤال بأين ومتى","passage":"نستخدم «أين» للسؤال عن المكان مثل «أين الكتاب؟»، ونستخدم «متى» للسؤال عن الوقت مثل «متى تبدأ الحصة؟». تساعد أداة السؤال على معرفة نوع الجواب المطلوب. نقرأ جملة السؤال بنبرة مناسبة ونضع علامة الاستفهام في آخرها.","q1":"أي أداة نسأل بها عن المكان؟","a1":"أين","w1":["متى","لماذا","كيف"],"q2":"أي أداة نسأل بها عن الوقت؟","a2":"متى","w2":["أين","من","ماذا"],"practice":"اكتب سؤالًا عن مكان الحقيبة وسؤالًا عن وقت بدء اللعب، ثم اسأل زميلك. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":3,"sem":1,"n":6,"title":"الظاهرة الإملائية — الفصل الأول","activity3":"writing","skill":"الظاهرة الإملائية: التاء في آخر الكلمة","passage":"تنتهي «شجرة» بتاء مربوطة «ة»، وتنتهي «بيت» بتاء مفتوحة «ت»، وتنتهي «وجه» بهاء «ه». نتأمل صورة آخر حرف وننطق الكلمة مع المعلم، ولا نستبدل الحروف عشوائيًا. يساعد جمع بعض الكلمات على تمييز التاء.","q1":"بأي حرف تنتهي «شجرة»؟","a1":"تاء مربوطة","w1":["تاء مفتوحة","هاء أصلية","واو"],"q2":"بأي حرف تنتهي «بيت»؟","a2":"تاء مفتوحة","w2":["تاء مربوطة","هاء","ألف"],"practice":"اكتب ست كلمات فيها تاء مربوطة ومفتوحة، ولوّن الحرف الأخير بلون مختلف. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":3,"sem":1,"n":7,"title":"الرسم الكتابي — الفصل الأول","activity3":"writing","skill":"الرسم الكتابي: حروف واضحة ومسافات","passage":"نكتب الكلمات من اليمين إلى اليسار، ونترك مسافة صغيرة واضحة بين كل كلمتين، مع المحافظة على مواضع النقاط. في «ذهبَ عليٌّ إلى البيت» نلاحظ أن الكلمات ثلاث وحدات متباعدة، وأن للحروف نقاطًا لا يجوز نسيانها.","q1":"ما الذي نفصل به بين كلمتين؟","a1":"مسافة مناسبة","w1":["نقطة فوق كل حرف","شرطة بين كل حرف","حذف آخر الحرف"],"q2":"ما الذي يجب المحافظة عليه عند كتابة «بيت»؟","a2":"شكل الحروف ونقاطها","w2":["إزالة النقاط","جمع الكلمات","قلب الاتجاه"],"practice":"انسخ ثلاث جمل قصيرة بخط واضح مع مسافات متساوية، ثم راجع النقاط. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":3,"sem":1,"n":8,"title":"التواصل الكتابي — الفصل الأول","activity3":"writing","skill":"التواصل الكتابي: بداية ووسط ونهاية","passage":"يمكن كتابة قصة صغيرة من ثلاث جمل: «أحضرَ فهدٌ ورقة. رسم شجرة جميلة. علّق الرسم في الفصل». تبدأ القصة بفكرة ثم حدث ثم نتيجة. يكتب الطالب جملة مفيدة بكل سطر ويختار كلمة مناسبة للتسلسل.","q1":"ماذا فعل فهد في الجملة الثانية؟","a1":"رسم شجرة","w1":["ذهب إلى البحر","أكل تفاحة","قرأ قصة"],"q2":"ما آخر حدث في القصة؟","a2":"علّق الرسم","w2":["أحضر الورقة","فتح الباب","زرع بذرة"],"practice":"اكتب ثلاث جمل عن عمل قمت به: البداية، ثم ما فعلته، ثم النتيجة. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":3,"sem":2,"n":1,"title":"الاستماع والتحدث — الفصل الثاني","activity3":"listening","skill":"الاستماع لفكرة النص والسبب","passage":"يقرأ المعلم: «استعار ناصر قصةً من مكتبة المدرسة. أعادها يوم الخميس؛ لأنه وعد أمين المكتبة بالحفاظ على الموعد». نص تدريبي أصلي يحتاج قراءة صوتية فعلية ولا يتضمن ملفًا صوتيًا مولدًا. يستمع الطالب بحثًا عن الفعل والسبب.","q1":"لماذا أعاد ناصر القصة يوم الخميس؟","a1":"لأنه وعد بالمحافظة على الموعد","w1":["لأن الحديقة أغلقت","لأنه نسي عنوانها","لأنه أراد إخفاءها"],"q2":"من أين استعار ناصر القصة؟","a2":"من مكتبة المدرسة","w2":["من متجر الألعاب","من محطة القطار","من الملعب"],"practice":"استمع للقصة واذكر سبب إعادة الكتاب ثم أعدها بجملة من إنشائك. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":3,"sem":2,"n":2,"title":"القراءة والفهم — الفصل الثاني","activity3":"reading","skill":"القراءة: ترتيب الأحداث والنتيجة","passage":"«وصلَ كريم إلى البستان. رأى الورود عطشى، فسقاها بالماء. في المساء بدت الأوراق نضرة». نقرأ النص ونحدد البداية والفعل الذي أدى إلى النتيجة. لا يصح أن ندّعي أن القصة تحدثت عن المطر؛ لم تذكره.","q1":"ماذا فعل كريم للورود؟","a1":"سقاها بالماء","w1":["قطفها كلها","نقلها إلى الصف","باعها"],"q2":"كيف بدت الأوراق في المساء؟","a2":"نضرة","w2":["ممزقة","مفقودة","ملونة بالأحمر حتمًا"],"practice":"رتب أحداث القصة باستخدام «أولًا، ثم، أخيرًا» واكتب جملة عن النتيجة. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":3,"sem":2,"n":3,"title":"الصنف اللغوي — الفصل الثاني","activity3":"writing","skill":"الصنف اللغوي: الجمع والمفرد","passage":"كلمة «قلم» مفرد، و«أقلام» جمع تكسير، و«طالبة» مفرد و«طالبات» جمع مؤنث سالم. يتغير شكل بعض الكلمات عند جمعها ولا يلزم أن يضاف حرف واحد في جميع الجموع. يراجع المتعلم المعنى وعدد الأشياء.","q1":"أي كلمة جمع لكلمة «قلم»؟","a1":"أقلام","w1":["قلمة","قلمان فقط","كتب"],"q2":"ما جمع «طالبة»؟","a2":"طالبات","w2":["طلابان","طالبي","قلمين"],"practice":"كوّن قائمة بخمسة أسماء مفردة وجموعها واستخدم كل جمع في جملة. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":3,"sem":2,"n":4,"title":"الوظيفة النحوية — الفصل الثاني","activity3":"writing","skill":"الوظيفة النحوية: فعل ومن قام به","passage":"في «فتحَ أحمدُ البابَ» يدل «فتحَ» على فعل، و«أحمدُ» من قام به، و«البابَ» الشيء الذي وقع عليه الفتح. يكفي للمتعلم في البداية فهم العلاقات داخل الجملة، ثم يتعرف بالتدريج إلى تسمية الفاعل والمفعول.","q1":"من قام بالفتح؟","a1":"أحمد","w1":["الباب","النافذة","القلم"],"q2":"ماذا فتح أحمد؟","a2":"الباب","w2":["الكتاب","الحقيبة","السيارة"],"practice":"اكتب ثلاث جمل عن أعمال منزلية آمنة ثم حدد من فعل العمل وما وقع عليه. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":3,"sem":2,"n":5,"title":"الأسلوب اللغوي — الفصل الثاني","activity3":"reading","skill":"الأسلوب اللغوي: النفي والطلب المهذب","passage":"«لا أعبثُ بالكتب» تعبير عن نفي فعل المتكلم في هذا السياق، و«من فضلك رتّب الكتب» طلب مهذب. تختلف صياغة الكلام بحسب المتحدث والمخاطب؛ نختار التعبير الواضح ولا نستعمل السخرية أو التجريح.","q1":"أي عبارة طلب مهذب؟","a1":"من فضلك رتّب الكتب","w1":["أنت لا تفهم","لا أريد الاستماع","كل كلامك خاطئ"],"q2":"ما الذي يفيده قول «لا أعبث بالكتب»؟","a2":"نفي العبث بالكتب","w2":["إثبات العبث","سؤال عن المكان","تعجب من الطقس"],"practice":"حوّل أمرين مباشرين إلى طلبين مهذبين، واكتب جملة نفي من إنشائك. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":3,"sem":2,"n":6,"title":"الظاهرة الإملائية — الفصل الثاني","activity3":"writing","skill":"الظاهرة الإملائية: حروف المد","passage":"في «قال» ألف مد بعد فتحة، وفي «يقول» واو مد بعد ضمة، وفي «قيل» ياء مد بعد كسرة. ننطق المقاطع بتمهل لنربط الصوت الطويل بحرفه، ولا نضيف حرف مد حيث لا يسمع الصوت الطويل في المثال.","q1":"ما حرف المد في «قال»؟","a1":"الألف","w1":["الواو","الياء","الهمزة"],"q2":"ما حرف المد في «قيل»؟","a2":"الياء","w2":["الألف","الواو","التاء"],"practice":"اكتب ثلاثة أمثلة لكل مد بالألف والواو والياء ثم اقرأها بصوت واضح. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":3,"sem":2,"n":7,"title":"الرسم الكتابي — الفصل الثاني","activity3":"writing","skill":"الرسم الكتابي: اتصال الحروف","passage":"في الكتابة العربية تتصل حروف كثيرة بما بعدها مثل الباء والسين في مواضعها، وهناك حروف لا تتصل بما بعدها مثل الألف والدال والراء. يساعد نسخ «باب» و«مدرسة» على ملاحظة بداية الكلمة ووسطها ونهايتها، ولا يتغير ترتيب الحروف.","q1":"أي حرف لا يتصل بما بعده عادة؟","a1":"الدال","w1":["الباء","السين","الميم"],"q2":"ما العنصر الذي نراجعه عند نسخ كلمة؟","a2":"اتصال الحروف ونقاطها وترتيبها","w2":["لون الورقة وحده","طول السطر فقط","الزينة حول الكلمة"],"practice":"انسخ كلمتين بحروف متصلة وأخريين تضمان حرفًا لا يتصل بما بعده، ووضّح مواضع الوصل. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":3,"sem":2,"n":8,"title":"التواصل الكتابي — الفصل الثاني","activity3":"writing","skill":"التواصل الكتابي: رسالة قصيرة","passage":"تتضمن الرسالة الودية تحية وسبب الكتابة وخاتمة لطيفة. مثال أصلي: «إلى صديقي سامي، أحب أن أخبرك أنني قرأت قصة ممتعة. هل ترغب في استعارتها؟ تحياتي، خالد». يحافظ الكاتب على وضوح المقصود واحترام المخاطب.","q1":"لمن وجّه خالد رسالته؟","a1":"إلى سامي","w1":["إلى المعلم فقط","إلى المدير","إلى أبيه"],"q2":"ماذا عرض خالد في الرسالة؟","a2":"إعارة قصة","w2":["شراء سيارة","إلغاء الرحلة","بيع مكتبة"],"practice":"اكتب رسالة من أربع جمل لصديق تشكره أو تدعوه لنشاط مناسب. مستوى الصف 3: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 3 — تدريب مهاري أصلي مستقل للفصل 2."}]'::jsonb)
 AS x(g integer,sem integer,n integer,title text,activity3 text,skill text,
      passage text,q1 text,a1 text,w1 text[],q2 text,a2 text,w2 text[],
      practice text,focus text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,saved_text
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='SA' AND c.id='f42518c1-c7bd-45da-bb37-69cf9eca0a56'::uuid
    AND g.grade_number=r.g AND u.semester=r.sem
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO x_count FROM public.student_lesson_progress sp WHERE sp.lesson_id=target_id;
  IF x_count<>0 THEN RAISE EXCEPTION 'SA_G1_3_PROGRESS_PRESENT_%',r.title; END IF;
  SELECT count(*) INTO x_count FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF x_count<>0 THEN RAISE EXCEPTION 'SA_G1_3_ATTEMPTS_PRESENT_%',r.title; END IF;
  IF char_length(coalesce(saved_text,''))>=350 THEN RAISE EXCEPTION 'SA_G1_3_NOT_SHORT_%',r.title; END IF;
  SELECT count(*) INTO a_count FROM public.lesson_activities WHERE lesson_id=target_id
    AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';
  IF a_count<>3 THEN RAISE EXCEPTION 'SA_G1_3_EXPECT_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET content='ضاديوم — إثراء لغوي مستقل لطلاب الصف '||r.g::text||
   ' بالمملكة العربية السعودية، الفصل '||r.sem::text||'. موضوع تدريبي أصلي تحت عنوان مهارة عامة، لا يمثل نص درس من كتاب رسمي أو مطابقة فهرسية معتمدة.'
   ||E'\n\n'||'الهدف: '||r.focus||' أن يطبق المتعلم '||r.skill||' على مثال جديد ويعلل رأيه.'
   ||E'\n\n'||'شرح وتدريب أصلي: '||r.passage
   ||E'\n\n'||'اختبار فهم وتطبيق: '||r.q1
   ||E'\n\n'||'اختبار ثان: '||r.q2
   ||E'\n\n'||'نشاط مستقل: '||r.practice
   ||E'\n\n'||'التمايز: يقدم مثال محلول وتمارين خطوة بخطوة لمن يحتاج الدعم؛ ويقدم للمتقدمين تفسيرًا ثانيًا أو مراجعة دليل مخالف. يجب أن يراجع المعلم الاستجابات المفتوحة.'
   ||E'\n\n'||'حالة المصدر: المحتوى غير رسمي ويستلزم الرجوع إلى الكتاب الفعلي. المدخل السابق محفوظ: '||coalesce(saved_text,''),
   updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET prompt=r.q1,
   content=content||jsonb_build_object('origin','DADYOOM_SA_G1_G3_TERMS_ORIGINAL_48_20261009','previousOrigin','DADYOOM_SA_OFFICIAL_2026_2027_V1',
    'notOfficialBook',true,'sourceVerification','pending','text',r.q1,
    'options',CASE ((r.n+r.sem+r.g)%4)
    WHEN 0 THEN jsonb_build_array(r.a1,r.w1[1],r.w1[2],r.w1[3])
    WHEN 1 THEN jsonb_build_array(r.w1[1],r.a1,r.w1[2],r.w1[3])
    WHEN 2 THEN jsonb_build_array(r.w1[1],r.w1[2],r.a1,r.w1[3])
    ELSE jsonb_build_array(r.w1[1],r.w1[2],r.w1[3],r.a1) END),
   answer=jsonb_build_object('correct',r.a1)
   WHERE lesson_id=target_id AND activity_order=1 AND activity_type='multiple_choice'
     AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';

  UPDATE public.lesson_activities SET prompt=r.q2,
   content=content||jsonb_build_object('origin','DADYOOM_SA_G1_G3_TERMS_ORIGINAL_48_20261009','previousOrigin','DADYOOM_SA_OFFICIAL_2026_2027_V1',
    'notOfficialBook',true,'sourceVerification','pending','text',r.q2,
    'options',CASE ((r.n+r.sem+r.g+1)%4)
    WHEN 0 THEN jsonb_build_array(r.a2,r.w2[1],r.w2[2],r.w2[3])
    WHEN 1 THEN jsonb_build_array(r.w2[1],r.a2,r.w2[2],r.w2[3])
    WHEN 2 THEN jsonb_build_array(r.w2[1],r.w2[2],r.a2,r.w2[3])
    ELSE jsonb_build_array(r.w2[1],r.w2[2],r.w2[3],r.a2) END),
   answer=jsonb_build_object('correct',r.a2)
   WHERE lesson_id=target_id AND activity_order=2 AND activity_type='multiple_choice'
     AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_SA_G1_G3_TERMS_ORIGINAL_48_20261009','previousOrigin','DADYOOM_SA_OFFICIAL_2026_2027_V1',
      'notOfficialBook',true,'sourceVerification','pending','humanReviewRequired',true,
      'text',r.practice,'audioGenerated',false)
    WHERE lesson_id=target_id AND activity_order=3 AND activity_type=r.activity3
      AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';

  SELECT count(*) INTO a_count FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_SA_G1_G3_TERMS_ORIGINAL_48_20261009';
  IF a_count<>3 THEN RAISE EXCEPTION 'SA_G1_3_INCOMPLETE_ACTIVITY_UPDATE_%',r.title; END IF;
 END LOOP;
END $dadyoom$;